users = []
with open('users.csv', newline='', encoding='utf-8') as f:
    for row in csv.DictReader(f):
        users.append(row)

by_id = {}
for u in users:
    by_id[str(u['id']).strip()] = u

PAID = 'paid'
totals = {}

def pick(d, *names):
    for n in names:
        if n in d:
            return d[n]
    return None

with open('orders.jsonl', encoding='utf-8') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        o = json.loads(line)
        uid = pick(o, 'user_id', 'userId', 'user', 'uid', 'id')
        if uid is None:
            continue
        uid = str(uid).strip()
        if uid not in by_id:
            continue
        status = pick(o, 'status')
        if str(status).strip().lower() != PAID:
            continue
        total = pick(o, 'total', 'amount', 'total_amount', 'totalAmount', 'price')
        try:
            total = float(total or 0)
        except (TypeError, ValueError):
            total = 0.0
        totals[uid] = totals.get(uid, 0.0) + total

report = []
for u in users:
    uid = str(u['id']).strip()
    report.append({
        'user': u['name'],
        'country': u['country'],
        'paid_total': round(totals.get(uid, 0.0), 2),
    })

report.sort(key=lambda r: (-r['paid_total'], r['user']))

with open('report.json', 'w', encoding='utf-8') as f:
    json.dump(report, f, ensure_ascii=False, indent=2)

